SELECT o.offering_code AS offeringCode, c.course_name AS courseName, school_class.class_name AS className, student.student_no AS studentNo, student.full_name AS studentName, guardian.full_name AS guardianName, guardian.mobile AS guardianMobile, enrollment.status, enrollment.enrolled_at AS enrolledAt FROM enrollment JOIN course_offering o ON o.id = enrollment.offering_id JOIN course c ON c.id = o.course_id JOIN student ON student.id = enrollment.student_id JOIN school_class ON school_class.id = student.class_id LEFT JOIN student_guardian primary_binding ON primary_binding.student_id = enrollment.student_id AND primary_binding.is_active = TRUE AND primary_binding.is_primary = TRUE LEFT JOIN guardian ON guardian.id = primary_binding.guardian_id WHERE enrollment.offering_id = #{offeringId}
AND enrollment.school_id = #{schoolId}
ORDER BY school_class.grade, school_class.class_name, student.student_no, enrollment.id

SELECT action.id, action.school_id AS schoolId, action.enrollment_id AS enrollmentId, action.offering_id AS offeringId, offering.offering_code AS offeringCode, course.course_name AS courseName, action.student_id AS studentId, student.full_name AS studentName, action.action_type AS actionType, action.related_enrollment_id AS relatedEnrollmentId, action.actor_user_id AS actorUserId, actor.display_name AS actorName, action.actor_role AS actorRole, action.acted_at AS actedAt FROM enrollment_action action JOIN course_offering offering ON offering.id = action.offering_id JOIN course ON course.id = offering.course_id JOIN student ON student.id = action.student_id JOIN sys_user actor ON actor.id = action.actor_user_id WHERE action.enrollment_id = #{enrollmentId}
AND action.school_id = #{schoolId}
AND action.guardian_id = #{guardianId}
AND action.student_id = #{studentId}
ORDER BY action.acted_at, action.id
